@file:OptIn(ExperimentalEncodingApi::class)

package id.homebase.api.image

import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * 64x48 HEICs written by ImageIO on macOS 27, rotated 90° (orientation 6), with GPS, a capture time and a body serial.
 * The left half is HDR-bright. [APPLE_GAINMAP_HEIC] has an iPhone-style Apple gain map with MakerNote tags 33 = 1.01
 * and 48 = 0.005 (headroom 2^2.65); [ISO_GAINMAP_HEIC] has an ISO 21496-1 gain map with a headroom of 4 (log2 2).
 */
internal object HeicGainmapTestFiles {
    val APPLE_GAINMAP_HEIC: ByteArray = Base64.decode("")
    val ISO_GAINMAP_HEIC: ByteArray = Base64.decode("")
    const val APPLE_HEADROOM_STOPS = 2.65
    const val ISO_HEADROOM_STOPS = 2.0
}
